func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, " == ")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle")
	}
	addends := strings.Split(eq[0], " + ")
	result := eq[1]

	words := append(addends, result)

	leading := map[rune]bool{}
	for _, w := range words {
		if len(w) > 1 {
			leading[w[0]] = true
		}
	}

	assignment := make(map[rune]int)
	used := make(map[int]bool)

	var solveCol func(col, carry int) bool
	solveCol = func(col, carry int) bool {
		if col == maxLen {
			return carry == 0
		}

		// Letters in this column, from addends.
		addLetters := make([]rune, 0, len(addends))
		for _, w := range addends {
			if col < len(w) {
				addLetters = append(addLetters, w[len(w)-1-col])
			}
		}
		var resLetter rune
		if col < len(result) {
			resLetter = result[len(result)-1-col]
		}

		// Unassigned letters in this column.
		var unassigned []rune
		seenInCol := map[rune]bool{}
		for _, r := range append(addLetters, resLetter) {
			if r == 0 {
				continue
			}
			if _, ok := assignment[r]; !ok && !seenInCol[r] {
				seenInCol[r] = true
				unassigned = append(unassigned, r)
			}
		}

		var assign func(i int) bool
		assign = func(i int) bool {
			if i == len(unassigned) {
				// Verify the column equation.
				sum := carry
				for _, r := range addLetters {
					sum += assignment[r]
				}
				if resLetter != 0 {
					if sum%10 != assignment[resLetter] {
						return false
					}
				} else if sum%10 != 0 {
					return false
				}
				return solveCol(col+1, sum/10)
			}
			r := unassigned[i]
			for d := 0; d <= 9; d++ {
				if used[d] {
					continue
				}
				if leading[r] && d == 0 {
					continue
				}
				assignment[r] = d
				used[d] = true
				if assign(i + 1) {
					return true
				}
				delete(assignment, r)
				used[d] = false
			}
			return false
		}
		return assign(0)
	}

